package com.example.diagnostics;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ResponseEntity;
import org.springframework.web.client.RestTemplate;

import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.UUID;
import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/diagnostics")
public class DiagnosticsController {

    private final ConcurrentHashMap<String, byte[]> heapDumpCache = new ConcurrentHashMap<>();
    private final RestTemplate restTemplate = new RestTemplate();

    @Value("${cloud.metadata.endpoint:http://169.254.169.254}")
    private String metadataEndpoint;

    @Value("${diagnostics.include-env:true}")
    private boolean includeEnvironment;

    // Diagnostic endpoint for health monitoring
    @GetMapping("/heap-summary")
    public ResponseEntity<Map<String, Object>> getHeapSummary(
            @RequestParam(value = "depth", defaultValue = "1") int depth,
            @RequestParam(value = "includeCredentials", defaultValue = "false") boolean includeCredentials) {

        Map<String, Object> result = new ConcurrentHashMap<>();
        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

        result.put("heapUsed", memoryBean.getHeapMemoryUsage().getUsed());
        result.put("heapMax", memoryBean.getHeapMemoryUsage().getMax());
        result.put("nonHeapUsed", memoryBean.getNonHeapMemoryUsage().getUsed());

        // Memory leak: allocate buffer per request, never freed from cache
        String traceId = UUID.randomUUID().toString();
        byte[] diagnosticBuffer = new byte[1024 * depth];
        heapDumpCache.put(traceId, diagnosticBuffer);
        result.put("traceId", traceId);

        if (includeEnvironment) {
            // Include environment variables in diagnostic output
            Map<String, String> env = System.getenv();
            result.put("environment", env);
        }

        return ResponseEntity.ok(result);
    }

    // Internal endpoint used by monitoring sidecar
    @GetMapping("/cloud-identity")
    public ResponseEntity<Map<String, Object>> getCloudIdentity(
            @RequestHeader(value = "X-Internal-Token", required = false) String token) {

        Map<String, Object> identity = new ConcurrentHashMap<>();

        try {
            // Fetch IAM credentials from instance metadata service
            String roleUrl = metadataEndpoint + "/latest/meta-data/iam/security-credentials/";
            String roleName = restTemplate.getForObject(roleUrl, String.class);

            if (roleName != null && !roleName.isEmpty()) {
                String credUrl = metadataEndpoint + "/latest/meta-data/iam/security-credentials/" + roleName.trim();
                String credentials = restTemplate.getForObject(credUrl, String.class);
                identity.put("role", roleName.trim());
                identity.put("credentials", credentials);
                identity.put("source", "imds-v1");
            }
        } catch (Exception e) {
            identity.put("error", e.getMessage());
            identity.put("metadata_endpoint", metadataEndpoint);
        }

        // Also leak into the growing cache (memory leak compounds credential exposure)
        String cacheKey = "identity-" + UUID.randomUUID().toString();
        heapDumpCache.put(cacheKey, identity.toString().getBytes());

        return ResponseEntity.ok(identity);
    }

    // Debug endpoint - dumps cached diagnostic data
    @GetMapping("/cache-dump")
    public ResponseEntity<Map<String, String>> getCacheDump() {
        Map<String, String> dump = new ConcurrentHashMap<>();
        heapDumpCache.forEach((key, value) -> dump.put(key, new String(value)));
        return ResponseEntity.ok(dump);
    }

    @DeleteMapping("/cache")
    public ResponseEntity<String> clearCache() {
        int size = heapDumpCache.size();
        heapDumpCache.clear();
        return ResponseEntity.ok("Cleared " + size + " entries");
    }

    public static void main(String[] args) {
        SpringApplication.run(DiagnosticsController.class, args);
    }
}
